import React, { useState } from 'react';
import { ChevronRight, ShieldCheck, Sparkles, X } from 'lucide-react';

const faqItems = [
  {
    id: 1,
    title: 'Do you handle international cases?',
    content: (
      <div>
        <p>Yes, we specialize in cross-border family law matters. Our firm has extensive experience with international divorce proceedings, custody disputes, and asset division cases involving parties from multiple countries.</p>
        <p><strong>Services:</strong> International matrimonial law, Hague Convention issues, cross-border asset tracing.</p>
      </div>
    ),
    visible: true
  },
  {
    id: 2,
    title: 'How long does a typical case take?',
    content: (
      <div>
        <p>The duration of a case can vary widely depending on the complexity and specific circumstances. Simple uncontested divorces may be resolved within 3-6 months, while complex cases involving contested custody or significant asset division can extend over 12-24 months.</p>
        <p><strong>Average timeline:</strong> Pre-trial discovery (2-4 months), mediation or negotiations (1-3 months), court proceedings (6-12 months).</p>
      </div>
    ),
    visible: true
  },
  {
    id: 3,
    title: 'What forms of payment do you accept?',
    content: (
      <div>
        <p>We accept a variety of payment methods including credit cards (Visa, Mastercard, American Express), ACH transfers, and cash (for initial consultations only). Our billing terms are clearly outlined in our engagement agreements.</p>
        <p><strong>Secure payment:</strong> 100% encrypted transactions processed through Stripe.</p>
      </div>
    ),
    visible: true
  },
  {
    id: 4,
    title: 'Are your attorneys available for 24/7 support?',
    content: (
      <div>
        <p>While our primary office hours are M-F from 9:00 AM to 5:00 PM, our legal advisors are available for urgent consultations outside these hours. Emergencies are promptly addressed through our secure messaging system.</p>
        <p><strong>Contact channels:</strong> Phone (800) 555-4321, email (info@hartwell-sawyer.com), live chat.</p>
      </div>
    ),
    visible: true
  },
  {
    id: 5,
    title: 'How do I schedule a consultation?',
    content: (
      <div>
        <p>Requesting a consultation is straightforward. Simply complete the form on our website or reach out directly via the secure contact portal. We will promptly review your case and arrange a time that fits your schedule, typically within 24-48 business hours.</p>
        <p><strong>Book now:</strong> <a href="#contact" className="text-blue-600 hover:underline">Request Consultation</a></p>
      </div>
    ),
    visible: true
  }
];

export default function Faq() {
  const [activeAccordion, setActiveAccordion] = useState(null);

  const toggleAccordion = (id) => {
    if (activeAccordion === id) {
      setActiveAccordion(null);
    } else {
      setActiveAccordion(id);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 p-8 sm:p-12">
      {/* Decorative Top Gradient Header */}
      <div className="relative h-48 sm:h-64">
        <div className="absolute top-0 left-0 right-0 bottom-0 bg-gradient-to-b from-indigo-600 via-purple-600 to-fuchsia-600 opacity-20" />
        <div className="absolute inset-0 bg-black opacity-60" />
        <div className="relative flex items-end justify-center p-8 text-center sm:p-12">
          <div className="w-full max-w-md text-center sm:max-w-2xl">
            <h1 className="text-3xl sm:text-4xl font-bold tracking-tight text-slate-100 sm:text-5xl">
              Frequently Asked Questions
            </h1>
            <p className="mt-4 text-slate-400">Get answers to common inquiries about our legal services.</p>
          </div>
        </div>
      </div>

      {/* Main FAQ Section */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="space-y-12">
          {faqItems.map((item) => (
            <div key={item.id} className="relative overflow-hidden rounded-2xl bg-white/5 p-6 shadow-2xl transition-all duration-300 hover:shadow-indigo-500/10">
              <div className="absolute -top-12 -right-12 -left-12 -bottom-12 bg-white/5 border border-white/10 rounded-2xl" />

              <div className="relative flex items-start justify-between p-4 pb-6 sm:p-6">
                <div className="flex items-start">
                  <div className="flex-shrink-0">
                    <ShieldCheck className="w-5 h-5 text-indigo-400" />
                  </div>
                  <div className="ml-3 min-w-0 flex-1 pt-0.5">
                    <h4 className="text-sm font-medium text-slate-400 tracking-wide">
                      {item.title}
                    </h4>
                    <div className="mt-2 text-sm text-slate-500">{item.content}</div>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => toggleAccordion(item.id)}
                  className="inline-flex items-center rounded-lg bg-white/5 px-3 py-2 text-slate-400 hover:text-slate-100 hover:bg-white/10"
                >
                  <ChevronRight className="w-4 h-4" />
                </button>
              </div>

              {activeAccordion === item.id && (
                <div className="animate-fade-in duration-500 p-6">
                  <div className="space-y-4">
                    {/* Accordion Expansion Animation */}
                    <div className="relative -mx-6 -my-6 bg-white/5 rounded-2xl border border-white/10 p-6 transition-all duration-300 hover:border-white/20">
                      {item.content}
                    </div>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
